// 死锁示例：两个线程按不同顺序获取两把锁
#include <pthread.h>
#include <stdio.h>

pthread_mutex_t lockA = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t lockB = PTHREAD_MUTEX_INITIALIZER;

// 线程1：先锁A再锁B
void* thread1(void* arg) {
    pthread_mutex_lock(&lockA);
    printf("Thread1: holding lockA\n");
    sleep(1); // 模拟处理
    pthread_mutex_lock(&lockB); // 等待 lockB，但被 thread2 持有
    printf("Thread1: holding lockA and lockB\n");
    pthread_mutex_unlock(&lockB);
    pthread_mutex_unlock(&lockA);
    return NULL;
}

// 线程2：先锁B再锁A（顺序不一致导致死锁）
void* thread2(void* arg) {
    pthread_mutex_lock(&lockB);
    printf("Thread2: holding lockB\n");
    sleep(1);
    pthread_mutex_lock(&lockA); // 等待 lockA，但被 thread1 持有
    printf("Thread2: holding lockB and lockA\n");
    pthread_mutex_unlock(&lockA);
    pthread_mutex_unlock(&lockB);
    return NULL;
}

// 解决方案：统一加锁顺序（都先锁A再锁B）
void* thread2_fixed(void* arg) {
    pthread_mutex_lock(&lockA); // 改为先锁A
    sleep(1);
    pthread_mutex_lock(&lockB);
    // ... 使用资源 ...
    pthread_mutex_unlock(&lockB);
    pthread_mutex_unlock(&lockA);
    return NULL;
}
